package com.academy.lms.enrollment;import com.academy.lms.security.CurrentUser;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController public class EnrollmentController {private final EnrollmentService service;public EnrollmentController(EnrollmentService s){service=s;}@PostMapping("/api/courses/{id}/enroll")@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasRole('STUDENT')")EnrollmentService.EnrollmentDto enroll(@PathVariable UUID id,Authentication a,HttpServletRequest r){return service.enroll(CurrentUser.id(a),id,r);}@GetMapping("/api/enrollments")@PreAuthorize("hasRole('STUDENT')")List<EnrollmentService.EnrollmentDto> mine(Authentication a){return service.mine(CurrentUser.id(a));}}

